insert into public.handbook_sections (chapter_id, slug, position, title_en, title_tr, body_en, body_tr, visibility, status, published_at, content_updated_at) values
  ((select id from c), 'about-this-handbook', 1, 'About this handbook', 'Bu el kitabı hakkında', '<p>This handbook gathers the information Right Holders and partners need to prepare their coverage of the 4th European Games Istanbul 2027. <strong>All values in this example are placeholders [EXEMPLO]</strong> and will be replaced with official information.</p><h2>How to use it</h2><p>Use the table of contents on the left to move between chapters and sections. Each heading has a link you can share with colleagues.</p><h3>Exporting to PDF</h3><p>You can download the complete handbook, one chapter or selected sections as a PDF in English or Turkish.</p>', '<p>Bu el kitabı, Yayın Hakkı Sahiplerinin ve ortakların 4. Avrupa Oyunları Istanbul 2027 yayınına hazırlanmaları için ihtiyaç duydukları bilgileri bir araya getirir. <strong>Bu örnekteki tüm değerler yer tutucudur [EXEMPLO]</strong> ve resmi bilgilerle değiştirilecektir.</p><h2>Nasıl kullanılır</h2><p>Bölümler arasında geçiş yapmak için soldaki içindekiler tablosunu kullanın. Her başlığın meslektaşlarınızla paylaşabileceğiniz bir bağlantısı vardır.</p><h3>PDF olarak dışa aktarma</h3><p>El kitabının tamamını, bir bölümünü veya seçilen kısımları İngilizce ya da Türkçe PDF olarak indirebilirsiniz.</p>', 'all', 'published', now(), now()),
  ((select id from c), 'key-dates', 2, 'Key dates', 'Önemli tarihler', '<p>The table below shows example milestones. <em>Dates are placeholders.</em></p><table><tbody><tr><th>Milestone [EXEMPLO]</th><th>Date [EXEMPLO]</th></tr><tr><td>Unilateral requests deadline</td><td>31 March 2027</td></tr><tr><td>IBC opening</td><td>1 June 2027</td></tr><tr><td>Opening Ceremony</td><td>25 June 2027</td></tr></tbody></table>', '<p>Aşağıdaki tablo örnek kilometre taşlarını gösterir. <em>Tarihler yer tutucudur.</em></p><table><tbody><tr><th>Kilometre taşı [EXEMPLO]</th><th>Tarih [EXEMPLO]</th></tr><tr><td>Tek taraflı talep son tarihi</td><td>31 Mart 2027</td></tr><tr><td>IBC açılışı</td><td>1 Haziran 2027</td></tr><tr><td>Açılış Töreni</td><td>25 Haziran 2027</td></tr></tbody></table>', 'all', 'published', now(), now());
insert into public.handbook_sections (chapter_id, slug, position, title_en, title_tr, body_en, body_tr, visibility, status, published_at, content_updated_at) values
  ((select id from c), 'role-of-the-host-broadcaster', 1, 'Role of the Host Broadcaster', 'Ev Sahibi Yayıncının rolü', '<p>Medialuso, as Host Broadcaster, produces the international signal of the Games and makes it available to Right Holders.</p><h2>Responsibilities</h2><ul><li>Production of the multilateral coverage.</li><li>Operation of the International Broadcast Centre (IBC).</li><li>Provision of unilateral services on request.</li></ul><p><strong>Medialuso''s responsibility ends with making the signal available.</strong></p>', '<p>Ev Sahibi Yayıncı olarak Medialuso, Oyunların uluslararası sinyalini üretir ve Yayın Hakkı Sahiplerinin kullanımına sunar.</p><h2>Sorumluluklar</h2><ul><li>Çok taraflı yayın prodüksiyonu.</li><li>Uluslararası Yayın Merkezinin (IBC) işletilmesi.</li><li>Talep üzerine tek taraflı hizmetlerin sağlanması.</li></ul><p><strong>Medialuso''nun sorumluluğu sinyalin kullanıma sunulmasıyla sona erer.</strong></p>', 'all', 'published', now(), now()),
  ((select id from c), 'signal-distribution', 2, 'Signal distribution (EBU)', 'Sinyal dağıtımı (EBU)', '<p>Worldwide distribution of the signal is handled by the <strong>EBU</strong>. Details of the distribution channels (satellite, fibre and streaming) will be published in the <em>Broadcast &amp; distribution</em> section.</p>', '<p>Sinyalin dünya çapında dağıtımı <strong>EBU</strong> tarafından yapılır. Dağıtım kanallarının (uydu, fiber ve yayın akışı) ayrıntıları <em>Yayın ve dağıtım</em> bölümünde yayınlanacaktır.</p>', 'all', 'published', now(), now());
insert into public.handbook_sections (chapter_id, slug, position, title_en, title_tr, body_en, body_tr, visibility, status, published_at, content_updated_at) values
  ((select id from c), 'video-and-audio', 1, 'Video and audio', 'Video ve ses', '<p>Example technical parameters. <em>Final values will be confirmed by the Host Broadcaster.</em></p><table><tbody><tr><th>Parameter</th><th>Value [EXEMPLO]</th></tr><tr><td>Video format</td><td>1080i50</td></tr><tr><td>Audio</td><td>Example channel configuration</td></tr><tr><td>Timecode</td><td>Example</td></tr></tbody></table><h2>Graphics</h2><p>The multilateral signal includes the Games graphics package. Clean feeds availability will be confirmed.</p>', '<p>Örnek teknik parametreler. <em>Nihai değerler Ev Sahibi Yayıncı tarafından onaylanacaktır.</em></p><table><tbody><tr><th>Parametre</th><th>Değer [EXEMPLO]</th></tr><tr><td>Video formatı</td><td>1080i50</td></tr><tr><td>Ses</td><td>Örnek kanal yapılandırması</td></tr><tr><td>Zaman kodu</td><td>Örnek</td></tr></tbody></table><h2>Grafikler</h2><p>Çok taraflı sinyal, Oyunların grafik paketini içerir. Temiz yayın akışlarının kullanılabilirliği onaylanacaktır.</p>', 'all', 'published', now(), now()),
  ((select id from c), 'production-levels', 2, 'Production levels', 'Prodüksiyon seviyeleri', '<p>Each venue is produced at one of three example levels:</p><ol><li><strong>Level 1</strong> – full coverage [EXEMPLO].</li><li><strong>Level 2</strong> – standard coverage [EXEMPLO].</li><li><strong>Level 3</strong> – basic coverage [EXEMPLO].</li></ol>', '<p>Her mekân üç örnek seviyeden birinde üretilir:</p><ol><li><strong>Seviye 1</strong> – tam kapsam [EXEMPLO].</li><li><strong>Seviye 2</strong> – standart kapsam [EXEMPLO].</li><li><strong>Seviye 3</strong> – temel kapsam [EXEMPLO].</li></ol>', 'all', 'published', now(), now()),
  ((select id from c), 'partner-notes', 3, 'Partner technical notes', 'Ortak teknik notları', '<p>Example of a section visible to <strong>partners only</strong> (EOC, Organising Committee, EBU).</p>', '<p><strong>Yalnızca ortakların</strong> (EOC, Organizasyon Komitesi, EBU) görebildiği örnek bölüm.</p>', 'partners', 'published', now(), now());
insert into public.faqs (category_id, position, question_en, question_tr, answer_en, answer_tr, status, published_at, content_updated_at) values
  ((select id from c), 1, '[EXEMPLO] Who can access this portal?', '[EXEMPLO] Bu portala kim erişebilir?', '<p>Approved Right Holders and partners. Each request is reviewed by the Host Broadcaster team.</p>', '<p>Onaylı Yayın Hakkı Sahipleri ve ortaklar. Her talep Ev Sahibi Yayıncı ekibi tarafından incelenir.</p>', 'published', now(), now()),
  ((select id from c), 2, '[EXEMPLO] How do I add a colleague?', '[EXEMPLO] Bir meslektaşımı nasıl eklerim?', '<p>Ask your colleague to request access with their professional email. They will be approved individually.</p>', '<p>Meslektaşınızdan kurumsal e-postasıyla erişim talep etmesini isteyin. Talebi ayrıca onaylanacaktır.</p>', 'published', now(), now());
insert into public.faqs (category_id, position, question_en, question_tr, answer_en, answer_tr, status, published_at, content_updated_at) values
  ((select id from c), 1, '[EXEMPLO] Who distributes the signal?', '[EXEMPLO] Sinyali kim dağıtıyor?', '<p>Worldwide distribution is handled by the EBU. Medialuso''s responsibility ends with making the signal available.</p>', '<p>Dünya çapındaki dağıtım EBU tarafından yapılır. Medialuso''nun sorumluluğu sinyalin kullanıma sunulmasıyla sona erer.</p>', 'published', now(), now()),
  ((select id from c), 2, '[EXEMPLO] How do I request unilateral services?', '[EXEMPLO] Tek taraflı hizmetleri nasıl talep ederim?', '<p>Use the <em>Service requests</em> form (available in a later stage of the portal).</p>', '<p><em>Hizmet talepleri</em> formunu kullanın (portalın sonraki bir aşamasında kullanıma sunulacaktır).</p>', 'published', now(), now()),
  ((select id from c), 3, '[EXEMPLO] Is there a Media Hub for graphics?', '[EXEMPLO] Grafikler için bir Medya Merkezi var mı?', '<p>Yes. The Media Hub contains the graphics package and promotional material only.</p>', '<p>Evet. Medya Merkezi yalnızca grafik paketini ve tanıtım materyallerini içerir.</p>', 'published', now(), now());
insert into public.glossary_terms (term_en, term_tr, definition_en, definition_tr, status, published_at, content_updated_at) values
  ('Multilateral feed', 'Çok taraflı yayın akışı', 'The international signal produced by the Host Broadcaster and offered to all Right Holders.', 'Ev Sahibi Yayıncı tarafından üretilen ve tüm Yayın Hakkı Sahiplerine sunulan uluslararası sinyal.', 'published', now(), now()),
  ('Unilateral', 'Tek taraflı', 'Coverage produced by a single Right Holder for its own audience.', 'Tek bir Yayın Hakkı Sahibinin kendi izleyicisi için ürettiği yayın.', 'published', now(), now()),
  ('ISO feed', 'ISO yayın akışı', 'An isolated camera signal recorded or distributed separately from the programme output.', 'Program çıkışından ayrı olarak kaydedilen veya dağıtılan yalıtılmış kamera sinyali.', 'published', now(), now()),
  ('IBC', 'IBC', 'International Broadcast Centre: the hub where broadcasters work during the Games.', 'Uluslararası Yayın Merkezi: yayıncıların Oyunlar boyunca çalıştığı merkez.', 'published', now(), now()),
  ('OB van', 'Yayın aracı (OB van)', 'Outside Broadcast vehicle with the production equipment for a venue.', 'Bir mekân için prodüksiyon ekipmanını taşıyan dış yayın aracı.', 'published', now(), now()),
  ('1080i50', '1080i50', 'High-definition video format: 1080 lines, interlaced, 50 fields per second.', 'Yüksek çözünürlüklü video formatı: 1080 satır, geçmeli, saniyede 50 alan.', 'published', now(), now()),
  ('Clean feed', 'Temiz yayın akışı', 'A signal without on-screen graphics.', 'Ekran grafikleri olmayan sinyal.', 'published', now(), now()),
  ('Commentary position', 'Yorumcu pozisyonu', 'A desk at the venue equipped for commentators.', 'Mekânda yorumcular için donatılmış masa.', 'published', now(), now()),
  ('Mixed zone', 'Karma bölge', 'Area where media can interview athletes after competition.', 'Medyanın yarışmadan sonra sporcularla röportaj yapabildiği alan.', 'published', now(), now()),
  ('Timecode', 'Zaman kodu', 'Time reference embedded in a video signal.', 'Video sinyaline gömülü zaman referansı.', 'published', now(), now());
