insert into public.legal_pages (slug, position, title_en, title_tr, body_en, body_tr, status, published_at, content_updated_at) values
  ('terms', 1, '[EXEMPLO] Terms of use', '[EXEMPLO] Kullanım koşulları', '<p>These example terms govern access to the Istanbul 2027 Right Holders Portal (the “Portal”), operated by Medialuso as Host Broadcaster of the 4th European Games.</p><p>Access is personal and limited to approved users. You must not share your credentials or redistribute information from the Portal outside your organisation without authorisation.</p><p>Information in the Portal is provided to help Right Holders and partners prepare their coverage. Worldwide signal distribution is handled by the EBU; Medialuso’s responsibility ends with making the signal available.</p><p>Medialuso may suspend access in case of misuse of the Portal or of its materials.</p>', '<p>Bu örnek koşullar, 4. Avrupa Oyunları’nın Ev Sahibi Yayıncısı Medialuso tarafından işletilen Istanbul 2027 Yayın Hakkı Sahipleri Portalı’na (“Portal”) erişimi düzenler.</p><p>Erişim kişiseldir ve onaylı kullanıcılarla sınırlıdır. Giriş bilgilerinizi paylaşmamalı ve Portal’daki bilgileri izinsiz olarak kuruluşunuz dışına dağıtmamalısınız.</p><p>Portal’daki bilgiler, Yayın Hakkı Sahiplerinin ve ortakların yayın hazırlıklarına yardımcı olmak için sunulur. Sinyalin dünya çapında dağıtımı EBU tarafından yapılır; Medialuso’nun sorumluluğu sinyalin kullanıma sunulmasıyla sona erer.</p><p>Portal’ın veya materyallerinin kötüye kullanılması durumunda Medialuso erişimi askıya alabilir.</p>', 'published', now(), now()),
  ('privacy', 2, '[EXEMPLO] Privacy policy', '[EXEMPLO] Gizlilik politikası', '<p>Example privacy notice. We process the personal data you provide at registration (name, professional email, organisation, country, job title, phone) to manage your access to the Portal.</p><p>We also record sign-ins and downloads for security and to measure the use of the Portal.</p><p>You can update your details from your profile, ask for a copy of your data, or ask for your account to be deleted at any time. Requests are handled by the Portal administrators.</p><p>Data is stored in the European Union.</p>', '<p>Örnek gizlilik bildirimi. Kayıt sırasında verdiğiniz kişisel verileri (ad, kurumsal e-posta, kuruluş, ülke, görev, telefon) Portal’a erişiminizi yönetmek için işliyoruz.</p><p>Güvenlik ve Portal kullanımını ölçmek amacıyla girişleri ve indirmeleri de kaydediyoruz.</p><p>Bilgilerinizi profilinizden güncelleyebilir, verilerinizin bir kopyasını isteyebilir veya hesabınızın silinmesini istediğiniz zaman talep edebilirsiniz. Talepler Portal yöneticileri tarafından işleme alınır.</p><p>Veriler Avrupa Birliği’nde saklanır.</p>', 'published', now(), now()),
  ('material', 3, '[EXEMPLO] Material usage terms', '[EXEMPLO] Materyal kullanım koşulları', '<p>Example material usage terms. Graphics, bumpers, curtains, promos and music in the Media Hub may only be used by Right Holders in their coverage of the Games, within their licensed territory.</p><p>Materials must not be altered in a way that misrepresents the Games or their partners.</p><p>You will be asked to accept these terms before your first download. Your acceptance is recorded.</p>', '<p>Örnek materyal kullanım koşulları. Medya Merkezi’ndeki grafikler, bumper’lar, perdeler, tanıtımlar ve müzik yalnızca Yayın Hakkı Sahipleri tarafından, lisanslı bölgelerinde Oyunların yayınında kullanılabilir.</p><p>Materyaller, Oyunları veya ortaklarını yanlış yansıtacak şekilde değiştirilmemelidir.</p><p>İlk indirmenizden önce bu koşulları kabul etmeniz istenecektir. Kabulünüz kaydedilir.</p>', 'published', now(), now());
